def number_tips(apps, schema_editor):
    """Keeps the order the tips were shown in, newest first."""
    RecipeTip = apps.get_model("cookbook", "RecipeTip")
    tips = RecipeTip.objects.order_by("recipe_id", "-id")
    previous_recipe, order = None, 0
    for tip in tips:
        order = order + 1 if tip.recipe_id == previous_recipe else 0
        previous_recipe = tip.recipe_id
        tip.order = order
    RecipeTip.objects.bulk_update(tips, ["order"])


